function dashboard(){const fav=tools.filter(t=>state.favorites.has(t.id)),recent=state.recent.map(id=>tools.find(t=>t.id===id)).filter(Boolean),notes=state.notes.slice(0,3),userProjects=projectSource(state),inc=state.transactions.filter(x=>x.amount>0).reduce((a,b)=>a+b.amount,0),out=state.transactions.filter(x=>x.amount<0).reduce((a,b)=>a+b.amount,0),hour=new Date().getHours(),greeting=hour<12?"Bom dia":hour<18?"Boa tarde":"Boa noite";return `<div class="home-head"><div><div class="home-kicker"><span class="eyebrow">${state.session?"Neon workspace":"Workspace operacional"}</span>${state.session?`<div id="syncStatus" class="sync-status ${syncLabel()[1]}"><i></i><span>${syncLabel()[0]}</span></div>`:""}</div><h1>${greeting}. O que vamos construir?</h1><p>Seu trabalho, projetos e ferramentas em um só lugar.</p></div><button class="home-search" data-action="command">⌕ Buscar <kbd>Ctrl K</kbd></button></div><div class="home-stats"><button data-go="tools"><span>Ferramentas</span><strong>${tools.length}</strong><small>${fav.length} favoritas</small></button><button data-go="projects"><span>Projetos</span><strong>${userProjects.length}</strong><small>${state.session?"na nuvem":"workspaces ativos"}</small></button><button data-go="notes"><span>Notas</span><strong>${state.notes.length}</strong><small>${state.session?"sincronizadas na nuvem":"salvas neste dispositivo"}</small></button><button data-go="finance"><span>Saldo</span><strong>${money(inc+out)}</strong><small>${state.transactions.length} movimentações</small></button></div><div class="quick-actions"><button data-go="notes">＋ <span><strong>Nova nota</strong><small>Registrar uma ideia</small></span></button><button data-go="flow">⌁ <span><strong>Novo fluxo</strong><small>Abrir whiteboard</small></span></button><button data-go="qrcode">▦ <span><strong>Gerar QR</strong><small>Criar QR Code</small></span></button><button data-go="tools">◫ <span><strong>Explorar tools</strong><small>Abrir biblioteca</small></span></button></div><div class="home-columns"><section><div class="section-head"><h2>Projetos</h2><button data-go="projects">Ver todos</button></div><div class="home-projects">${userProjects.map(p=>`<button data-go="projects"><i>${esc(p.name.slice(0,2).toUpperCase())}</i><span><strong>${esc(p.name)}</strong><small>${esc(p.status)}</small></span><b>→</b></button>`).join("")}</div></section><section><div class="section-head"><h2>Notas recentes</h2><button data-go="notes">Abrir notas</button></div><div class="home-notes">${notes.length?notes.map(n=>`<button data-go="notes"><strong>${esc(n.title||"Sem título")}</strong><span>${esc((n.body||"").slice(0,80))}</span></button>`).join(""):`<div class="home-empty">Nenhuma nota ainda.<button data-go="notes">Criar primeira nota</button></div>`}</div></section></div><div class="section-head"><h2>Acesso recente</h2><button data-go="tools">Biblioteca</button></div><div class="grid">${(recent.length?recent:fav.length?fav:tools.slice(0,4)).slice(0,4).map(toolCard).join("")}</div>`}
