function filteredTools(q){let list=tools.filter(t=>`${t.name} ${t.description} ${t.category}`.toLowerCase().includes(q.toLowerCase()));if(category==="Favoritos")list=list.filter(t=>state.favorites.has(t.id));else if(category==="Recentes"){const pos=new Map(state.recent.map((id,i)=>[id,i]));list=list.filter(t=>pos.has(t.id)).sort((x,y)=>pos.get(x.id)-pos.get(y.id))}else if(category==="Mais usados")list=list.filter(t=>(state.usage[t.id]||0)>0).sort((x,y)=>(state.usage[y.id]||0)-(state.usage[x.id]||0));else if(category!=="Todos")list=list.filter(t=>t.category===category);return list}
