function sortNotes(list,sort="updated"){return [...list].sort((a,b)=>{if(a.pinned!==b.pinned)return a.pinned?-1:1;if(sort==="title")return(a.title||"").localeCompare(b.title||"","pt-BR");if(sort==="created")return(b.createdAt||0)-(a.createdAt||0);return(b.updatedAt||b.createdAt||0)-(a.updatedAt||a.createdAt||0)})}
