async function noteDialog(note=null){if(!window.Swal)return;const r=await Swal.fire({title:note?"Editar nota":"Nova nota",width:640,customClass:{popup:"td-modal td-note-modal",title:"td-modal-title",htmlContainer:"td-modal-body",actions:"td-modal-actions",confirmButton:"td-modal-confirm",cancelButton:"td-modal-cancel"},html:`<div class="td-field"><label>Título</label><input id="swNoteTitle" maxlength="100" placeholder="Ex.: Ideias para o projeto" value="${esc(note?.title||"")}"></div><div class="td-field"><label>Conteúdo</label><textarea id="swNoteBody" class="note-editor" maxlength="6000" placeholder="Escreva sua nota...">${esc(note?.body||"")}</textarea></div><div class="td-field"><label>Tags <span>separe por vírgulas</span></label><input id="swNoteTags" maxlength="160" placeholder="projeto, ideia, importante" value="${esc((note?.tags||[]).join(", "))}"></div>`,showCancelButton:true,confirmButtonText:note?"Salvar alterações":"Salvar nota",cancelButtonText:"Cancelar",background:"#080808",color:"#fff",confirmButtonColor:"#fff",preConfirm:()=>{const title=document.querySelector("#swNoteTitle").value.trim(),body=document.querySelector("#swNoteBody").value.trim(),tags=[...new Set(document.querySelector("#swNoteTags").value.split(",").map(x=>x.trim().toLowerCase()).filter(Boolean))].slice(0,8);if(!title&&!body){Swal.showValidationMessage("Escreva um título ou conteúdo");return false}return{title,body,tags}}});if(!r.isConfirmed)return;const now=Date.now();if(note)Object.assign(note,r.value,{updatedAt:now});else state.notes.unshift({id:makeCloudId(),...r.value,pinned:false,favorite:false,createdAt:now,updatedAt:now});store.set("td:notes",state.notes);store.set("td:sync:pending",true);queueCloudSync();audit("Notas",note?"edit":"create",r.value.title||"Sem título");toast(note?"Nota atualizada":"Nota criada");render()}
function duplicateNote(id){const n=state.notes.find(x=>x.id===id);if(!n)return;const now=Date.now();state.notes.unshift({...n,id:makeCloudId(),title:(n.title||"Sem título")+" — cópia",pinned:false,createdAt:now,updatedAt:now});store.set("td:notes",state.notes);store.set("td:sync:pending",true);queueCloudSync();audit("Notas","duplicate",n.title||"Sem título");toast("Nota duplicada");render()}
async function noteMenu(id){const n=state.notes.find(x=>x.id===id);if(!n)return;const r=await Swal.fire({title:n.title||"Nota",html:`<div class="crud-menu"><button id="swDuplicateNote">⧉ Duplicar nota</button></div>`,showDenyButton:true,showCancelButton:true,confirmButtonText:"Editar",denyButtonText:"Excluir",cancelButtonText:"Fechar",background:"#080808",color:"#fff",confirmButtonColor:"#fff",denyButtonColor:"#3a1010",didOpen:()=>{document.querySelector("#swDuplicateNote").onclick=()=>{Swal.close();duplicateNote(id)}}});if(r.isConfirmed)noteDialog(n);else if(r.isDenied){const ok=await Swal.fire({title:"Excluir nota?",text:"Esta ação não poderá ser desfeita.",icon:"warning",showCancelButton:true,confirmButtonText:"Excluir",cancelButtonText:"Cancelar",background:"#080808",color:"#fff",confirmButtonColor:"#fff"});if(ok.isConfirmed){state.notes=state.notes.filter(x=>x.id!==id);store.set("td:notes",state.notes);deleteCloudRecord("notes",id).catch(e=>{console.warn("Delete note sync:",e);store.set("td:sync:pending",true)});audit("Notas","delete",n.title||"Sem título");rememberDelete("note",n);render()}}}
let lastDeleted=null;
function rememberDelete(kind,item){lastDeleted={kind,item};toast("Item excluído","info")}
function undoDelete(){if(!lastDeleted)return;const {kind,item}=lastDeleted;if(kind==="note"){state.notes.unshift(item);store.set("td:notes",state.notes)}else{state.transactions.unshift(item);store.set("td:transactions",state.transactions)}store.set("td:sync:pending",true);queueCloudSync();lastDeleted=null;toast("Item restaurado");render()}
const money=v=>(v/100).toLocaleString("pt-BR",{style:"currency",currency:"BRL"});
function monthKey(ts){const d=new Date(ts);return d.getFullYear()+"-"+String(d.getMonth()+1).padStart(2,"0")}
function personalFinanceFilter(t){if(financeScope!=="personal")return true;return matchesPersonalFinanceFilter(t,{memberFilter:financeMemberFilter,members:financeMembers,userId:state.session?.user?.id||""})}
function financeView(){const scoped=state.transactions.filter(t=>(t.financeScope||"personal")===financeScope).filter(personalFinanceFilter),months=[...new Set(scoped.map(t=>monthKey(t.createdAt)))].sort().reverse(),current=new Date().getFullYear()+"-"+String(new Date().getMonth()+1).padStart(2,"0"),month=months.includes(current)?current:(months[0]||current),list=scoped.filter(t=>monthKey(t.createdAt)===month),inc=list.filter(x=>x.amount>0).reduce((a,b)=>a+b.amount,0),out=list.filter(x=>x.amount<0).reduce((a,b)=>a+b.amount,0),cats=[...new Set(scoped.map(t=>t.category||"Geral"))].sort();return `<div class="module-head"><div class="hero"><span class="eyebrow">Finance workspace</span><h1>Financeiro</h1><p>Patrimônio pessoal e caixa empresarial separados, sincronizados no Neon.</p></div><div class="module-actions"><button class="ghost-action" id="importFinanceBtn">↑ Importar</button><input id="importFinanceFile" type="file" accept="application/json,.json" hidden><button class="ghost-action" id="backupFinanceBtn">↓ Backup</button><button class="ghost-action" id="exportFinanceBtn">↓ CSV</button><button class="primary" id="newTxBtn">＋ Nova transação</button></div></div>${financeScopeTabs(financeScope,financeEntities)}${financeScope==="personal"?familyWorkspace(financeMembers,financeAccounts,financeMemberFilter):""}<div class="crud-undo" id="crudUndo" hidden><span>Item removido</span><button id="undoDeleteBtn">↶ Desfazer</button></div><div class="grid finance-summary"><article class="card"><p>Entradas do período</p><div class="money positive" id="sumIn">${money(inc)}</div></article><article class="card"><p>Saídas do período</p><div class="money negative" id="sumOut">${money(out)}</div></article><article class="card"><p>Resultado</p><div class="money" id="sumBalance">${money(inc+out)}</div></article><article class="card"><p>Movimentações</p><div class="money" id="sumCount">${list.length}</div></article></div><div class="module-toolbar finance-toolbar"><div class="tool-search-wrap">⌕<input class="search" id="txSearch" placeholder="Pesquisar descrição, categoria ou contraparte..."></div><input id="txMonth" type="month" value="${month}"><select id="txFilter"><option value="all">Todas</option><option value="in">Entradas</option><option value="out">Saídas</option></select><select id="txCategory"><option value="all">Todas categorias</option>${cats.map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join("")}</select></div><div class="finance-breakdown" id="financeBreakdown">${renderBreakdown(list)}</div><div id="txList">${renderTransactions(list)}</div><div class="tools-empty" id="txEmpty" ${list.length?"hidden":""}><strong>Nenhuma movimentação neste período</strong><p>${financeScope==="business"?"Adicione receitas e despesas do CNPJ.":"Adicione suas receitas e despesas pessoais."}</p><button class="primary" id="emptyNewTx">＋ Nova transação</button></div>`}
function renderBreakdown(list){const m={};list.filter(t=>t.amount<0).forEach(t=>m[t.category||"Geral"]=(m[t.category||"Geral"]||0)+Math.abs(t.amount));const total=Object.values(m).reduce((a,b)=>a+b,0);return Object.entries(m).sort((a,b)=>b[1]-a[1]).slice(0,5).map(([k,v])=>`<div><span><b>${esc(k)}</b><small>${money(v)}</small></span><i><em style="width:${total?Math.round(v/total*100):0}%"></em></i></div>`).join("")}
function downloadFile(name,content,type="text/plain"){const a=document.createElement("a"),url=URL.createObjectURL(new Blob([content],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function importNotes(file){try{const data=JSON.parse(await file.text()),list=Array.isArray(data)?data:data.notes;if(!Array.isArray(list))throw 0;const valid=list.filter(n=>n&&typeof n==="object").map(n=>({...n,id:/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(n.id||"")?n.id:makeCloudId(),createdAt:n.createdAt||Date.now(),updatedAt:n.updatedAt||n.createdAt||Date.now(),tags:Array.isArray(n.tags)?n.tags:[]}));state.notes=[...valid,...state.notes.filter(n=>!valid.some(x=>x.id===n.id))];store.set("td:notes",state.notes);store.set("td:sync:pending",true);queueCloudSync();audit("Notas","import",valid.length+" notas");toast(valid.length+" notas importadas");render()}catch{toast("Backup de notas inválido","error")}}
function exportNotes(){const payload={app:"Tools Digital",version:"4.2.1",exportedAt:new Date().toISOString(),notes:state.notes};downloadFile("tools-digital-notas-"+new Date().toISOString().slice(0,10)+".json",JSON.stringify(payload,null,2),"application/json");toast("Backup de notas exportado")}
function exportFinanceBackup(){const payload={app:"Tools Digital",version:"4.2.1",exportedAt:new Date().toISOString(),transactions:state.transactions};downloadFile("tools-digital-financeiro-backup-"+new Date().toISOString().slice(0,10)+".json",JSON.stringify(payload,null,2),"application/json");toast("Backup financeiro exportado")}
async function importFinance(file){try{const data=JSON.parse(await file.text()),list=Array.isArray(data)?data:data.transactions;if(!Array.isArray(list))throw 0;const valid=list.filter(t=>t&&typeof t==="object"&&t.description&&Number.isFinite(Number(t.amount))).map(t=>({...t,id:/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(t.id||"")?t.id:makeCloudId(),amount:Number(t.amount),category:t.category||"Geral",createdAt:Number(t.createdAt)||Date.now(),updatedAt:Number(t.updatedAt)||Number(t.createdAt)||Date.now()}));state.transactions=[...valid,...state.transactions.filter(t=>!valid.some(x=>x.id===t.id))];store.set("td:transactions",state.transactions);store.set("td:sync:pending",true);queueCloudSync();audit("Financeiro","import",valid.length+" transações");toast(valid.length+" transações importadas");render()}catch{toast("Backup financeiro inválido","error")}}
function exportFinance(){const rows=[["Data","Descrição","Categoria","Tipo","Valor"],...[...state.transactions].sort((a,b)=>b.createdAt-a.createdAt).map(t=>[new Date(t.createdAt).toLocaleDateString("pt-BR"),t.description,t.category||"Geral",t.amount>0?"Entrada":"Saída",(t.amount/100).toFixed(2).replace(".",",")])];const csv=rows.map(r=>r.map(v=>'"'+String(v??"").replaceAll('"','""')+'"').join(";")).join("\n");downloadFile("tools-digital-financeiro-"+new Date().toISOString().slice(0,10)+".csv","\ufeff"+csv,"text/csv;charset=utf-8");toast("Financeiro exportado em CSV")}
