function toast(message,icon="success"){if(window.Swal){Swal.fire({toast:true,position:"top-end",icon,title:message,showConfirmButton:false,timer:1800,timerProgressBar:true,background:"#080808",color:"#fff"});return}const t=$("#toast");t.textContent=message;t.classList.add("show");setTimeout(()=>t.classList.remove("show"),1800)}
const overlay=$("#commandOverlay"),input=$("#commandInput"),results=$("#commandResults"),modules=[["dashboard","Início","Workspace"],["tools","Ferramentas","Módulo"],["projects","Projetos","Módulo"],["flow","Fluxo Tools","Módulo"],["qrcode","QR Code","Módulo"],["notes","Notas","Módulo"],["finance","Financeiro","Módulo"],["account","Minha conta","Módulo"]];let commandIndex=0,commandItems=[];
function command(q=""){const term=q.trim().toLowerCase(),mods=modules.filter(x=>!term||(`${x[1]} ${x[2]}`).toLowerCase().includes(term)).map(x=>({kind:"module",id:x[0],name:x[1],meta:x[2]})),ts=tools.filter(t=>!term||(`${t.name} ${t.category} ${t.description}`).toLowerCase().includes(term)).sort((a,b)=>(state.usage[b.id]||0)-(state.usage[a.id]||0)).slice(0,10).map(t=>({kind:"tool",id:t.id,name:t.name,meta:t.category+" · "+t.description}));commandItems=[...mods,...ts].slice(0,12);commandIndex=0;results.innerHTML=commandItems.length?commandItems.map((x,i)=>`<div class="command-result ${i===0?"selected":""}" data-command-index="${i}"><i>${x.kind==="module"?"⌘":"↗"}</i><div><strong>${esc(x.name)}</strong><p>${esc(x.meta)}</p></div></div>`).join(""):`<div class="command-empty">Nenhum resultado encontrado</div>`;results.querySelectorAll("[data-command-index]").forEach(x=>x.onclick=()=>runCommand(+x.dataset.commandIndex))}
function paintCommandSelection(){results.querySelectorAll("[data-command-index]").forEach((x,i)=>{x.classList.toggle("selected",i===commandIndex);if(i===commandIndex)x.scrollIntoView({block:"nearest"})})}
function runCommand(i=commandIndex){const x=commandItems[i];if(!x)return;x.kind==="module"?goTo(x.id):openTool(x.id);closeCommand()}
function openCommand(){overlay.hidden=false;input.value="";command();setTimeout(()=>input.focus(),0)}
function closeCommand(){overlay.hidden=true}
$("#commandBtn").onclick=openCommand;input.oninput=e=>command(e.target.value);document.addEventListener("keydown",e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==="k"){e.preventDefault();openCommand();return}if(overlay.hidden)return;if(e.key==="Escape"){closeCommand();return}if(e.key==="ArrowDown"){e.preventDefault();commandIndex=Math.min(commandIndex+1,commandItems.length-1);paintCommandSelection()}else if(e.key==="ArrowUp"){e.preventDefault();commandIndex=Math.max(commandIndex-1,0);paintCommandSelection()}else if(e.key==="Enter"){e.preventDefault();runCommand()}});overlay.onclick=e=>{if(e.target===overlay)closeCommand()};
