if("serviceWorker"in navigator)window.addEventListener("load",async()=>{try{swRegistration=await navigator.serviceWorker.register("./sw.js",{updateViaCache:"none"});if(swRegistration.waiting)swRegistration.waiting.postMessage({type:"SKIP_WAITING"});swRegistration.addEventListener("updatefound",()=>{const w=swRegistration.installing;if(!w)return;w.addEventListener("statechange",()=>{if(w.state==="installed"&&navigator.serviceWorker.controller)w.postMessage({type:"SKIP_WAITING"})})});navigator.serviceWorker.addEventListener("controllerchange",()=>{if(refreshing)return;refreshing=true;location.reload()});setTimeout(()=>checkForUpdates(false),1500)}catch{}});
document.addEventListener("visibilitychange",()=>{if(document.visibilityState==="visible"&&swRegistration)checkForUpdates(false)});
window.addEventListener("online",()=>{if(swRegistration)checkForUpdates(false);if(state.session){store.set("td:sync:pending",true);queueCloudSync();toast("Conexão restaurada · sincronizando")}});window.addEventListener("offline",()=>{paintSyncStatus();toast("Modo offline ativado","info")});
window.__tdState=state;clearTimeout(window.__tdBootTimer);bootstrapApp({
 restoreSession:()=>restoreUserSession({getSession,loadAccountData,hydrateCloud,state}),
 render,
 onReady:()=>{const requested=location.hash.replace(/^#/,"");view=state.session&&["dashboard","tools","projects","flow","qrcode","notes","finance","account"].includes(requested)?requested:state.session?"dashboard":"account";setTimeout(()=>handleFamilyWelcome(),250)},
 onError:e=>{console.warn("Bootstrap:",e);clearSessionState(state);view="account"}
});
